<?php	require_once('../../helpers/func_main.php');	require_once('../../conf_system.php');	require_once('classes/class_api.m3.php');    	// Convert data to json    $data = json_decode(file_get_contents('php://input'),true);     //Parse data from JSON    $userid          = $data["data"]["userid"];     $token           = $data["data"]["access_token"];     $pagenumber      = $data["data"]["pagenumber"];     $pagerecordcount = $data["data"]["pagerecordcount"];     $searchkey       = $data["data"]["searchkey"];     // Set default values    $message='Success';    $statuscode=0;    // Create class object    $api = new API();    if ($api->validateToken($userid, $token))    {        $dashboard=$api->loadSearchResult($userid,$pagenumber,$pagerecordcount,$searchkey);        $users=$api->loadSearchResultUser($userid,$pagenumber,$pagerecordcount,$searchkey);        $groups=$api->loadSearchResultGroup($userid,$pagenumber,$pagerecordcount,$searchkey);        http_response_code(200);    }    else    {        $message='Invalid token';        $statuscode=100;        http_response_code(401);    }    $response=array();    $settings =array(            "imageurl" => $api->imageUrl(),            "profileImageurl" => $api->profileImageUrl(),            "postBaseUrl" => $api->postBaseUrl()        );	$status =array(            "message" => $message,            "statuscode" => $statuscode        );    $response["dashboard"] = $dashboard;    $response["users"] = $users;    $response["groups"] = $groups;    $response["settings"] = $settings;    $response["status"] =  $status;    // show response data in json format    echo json_encode($response);?>